+                    'farewell' => 'Adiós'
+                ]
+            ]))
+        ]);
+
+        $result = $engine->localizeObject([
+            'greeting' => 'Hello',
+            'farewell' => 'Goodbye'
+        ], [
+            'sourceLocale' => 'en',
+            'targetLocale' => 'es'
+        ]);
+
+        $this->assertEquals([
+            'greeting' => 'Hola',
+            'farewell' => 'Adiós'
+        ], $result);
+    }
+
+    public function testBatchLocalizeText()
+    {
+        $engine = $this->createMockEngine([
+            new Response(200, [], json_encode([
+                'data' => ['text' => 'Hola, mundo!']
+            ])),
