+                aggregated.choices[index].message.tool_calls[toolCallIndex]
+                  .function.arguments,
+              );
+              const newArgs = String(toolCallDelta.function.arguments);
+              aggregated.choices[index].message.tool_calls[
+                toolCallIndex
+              ].function.arguments = existingArgs + newArgs;
+            }
+          }
+        }
+      }
