+fn get_bezier_points(x1: f32, y1: f32, data: &[f32]) -> Vec<f32> {
+    let mut out = Vec::with_capacity(2 + data.len());
+    out.push(x1);
+    out.push(y1);
+    out.extend_from_slice(data);
+    out
+}
