+}
+
+#[test]
+fn axis_projection_intersection_overlaps() {
+    let rects = [rect(10.0, 10.0, 30.0, 30.0), rect(20.0, 15.0, 40.0, 10.0)];
+    let inter = axis_projection_intersection(&rects, Axis::X);
+    assert_eq!(inter, Some([15.0, 25.0]));
+}

