+                    eprintln!("❌ MCP chat error: {}", e);
+                    std::process::exit(1);
+                }
+            });
+        }
+        McpCommands::Exec(args) => {
+            runtime.block_on(async {
+                let transport = parse_transport(args.url, args.command);
+                if let Err(e) = mcp_client::execute_command(transport, args.tool, args.args).await {
