+        services.AddSingleton<IDockSerializer, DockSerializer>();
+        services.AddSingleton<IDockState, DockState>();
+    }
+
+    public static AppBuilder BuildAvaloniaApp()
+        => AppBuilder.Configure<App>()
+            .UsePlatformDetect()
+            .WithInterFont()
+            .UseReactiveUI()
+            .LogToTrace();
+}

