+          {viewCount !== null && viewCount > 10 && session?.user?.email && (
+            <div className="rounded-md bg-gray-50 p-3 text-sm dark:bg-gray-900">
+              <p className="mb-2 font-medium text-muted-foreground">
+                Large export detected ({viewCount} views)
