+              >
+                Email to {session.user.email}
+              </button>
+            </div>
+          )}
+
+          {(!viewCount || viewCount <= 10) && (
+            <div className="text-sm text-gray-500">
+              Your export will be ready shortly...
+            </div>
+          )}
+        </div>
+      </div>
+    </div>
+  );
+}

