+    }
+  );
+
+  return (
+    <div>
+      <p>Status: {isDebouncing ? "Debouncing..." : "Ready"}</p>
+      <button onClick={() => debouncedLog("Button clicked!")}>
+        Click rapidly (leading + trailing + maxWait)
+      </button>
+      <div>
+        <h4>Logs:</h4>
